/* Keypad hit test: '7','4','1' / '8','5','2' / '9','6','6' by column/row. */
uint8_t opeu_supply_keypad_hit(uint8_t ds[65536], uint16_t x, uint16_t y) {
  uint16_t a;
  uint8_t  b;
  b = 0xff;
  a = W16(PX << 3);
  if (W16(a + 0x48) <= x && W16(a + 0x68) > x) {
    if (W16(PY + 0x23) <= y && W16(PY + 0x3f) > y)
      b = '7';
    if (W16(PY + 0x3f) <= y && W16(PY + 0x5b) > y)
      b = '4';
    if (W16(PY + 0x5b) <= y && W16(PY + 0x77) > y)
      b = '1';
  }
  if (W16(a + 0x68) <= x && W16(a + 0x98) > x) {
    if (W16(PY + 0x23) <= y && W16(PY + 0x3f) > y)
      b = '8';
    if (W16(PY + 0x3f) <= y && W16(PY + 0x5b) > y)
      b = '5';
    if (W16(PY + 0x5b) <= y && W16(PY + 0x77) > y)
      b = '2';
  }
  if (W16(a + 0x98) <= x && W16(a + 0xb8) > x) {
    if (W16(PY + 0x23) <= y && W16(PY + 0x3f) > y)
      b = '9';
    if (W16(PY + 0x3f) <= y && W16(PY + 0x5b) > y)
      b = '6';
    if (W16(PY + 0x5b) <= y && W16(PY + 0x77) > y)
      b = '6';
  }
  return b;
}

/* Mouse mode: right button = Enter (13); a left click on keypad keys 8/5/2
 * selects row 0/1/2 (returning 0xff). Keyboard mode returns the key. */
uint8_t opeu_supply_input(uint8_t ds[65536], SupplyEvent event, uint16_t row) {
  uint16_t a, b;
  uint8_t  c;
  if (INPUT_MODE) {
    MOUSE_SHOW();
    INPUT_DELAY(3);
    for (;;) {
      MOUSE_POSITION(a, b);
      if (RIGHT_DOWN()) {
        c = 13;
        break;
      }
      if (LEFT_DOWN()) {
        c = KEYPAD(a, b);
        if (c == '8') {
          SET_ROW(0);
          c = 0xff;
        }
        if (c == '5') {
          SET_ROW(1);
          c = 0xff;
        }
        if (c == '2') {
          SET_ROW(2);
          c = 0xff;
        }
        break;
      }
    }
    MOUSE_HIDE();
    return c;
  }
  return KEY();
}

void opeu_supply_set(uint8_t ds[65536], uint8_t side, uint8_t row,
                     uint8_t column, uint16_t value) {
  uint16_t at            = TABLE_AT(side, row, column);
  ds[at]                 = (uint8_t)value;
  ds[(uint16_t)(at + 1)] = (uint8_t)(value >> 8);
}

uint16_t opeu_supply_get(const uint8_t ds[65536], uint8_t side, uint8_t row,
                         uint8_t column) {
  return WORD(TABLE_AT(side, row, column));
}

/* Restore the panel background and centre two names of at most ten characters. */
void opeu_supply_draw(uint8_t ds[65536], SupplyEvent event, uint16_t first,
                      uint16_t second) {
  INT16 a;
  RESTORE();
  a = LENGTH(first);
  if (a > 10)
    a = 10;
  POSITION(HALF(a) + PX + 2, PY + 14);
  PRINT1(NAME_FORMAT, first);
  a = LENGTH(second);
  if (a > 10)
    a = 10;
  POSITION(HALF(a) + PX + 20, PY + 14);
  PRINT1(NAME_TEXT, second);
}

/* Right-aligned decimal digits drawn leftwards from x; zero draws one digit. */
void opeu_supply_digits(uint8_t ds[65536], SupplyEvent event, uint16_t x,
                        uint16_t y, uint16_t value) {
  for (;; x -= 6) {
    GLYPH(x, y, 0U, BLANK_GLYPH);
    GLYPH(x, y, 7, DIGIT_GLYPH(value % 10));
    if (!(value /= 10))
      break;
  }
}

